#!/usr/bin/env bash
# picsee release signing secrets wizard (#217). Run from the repository root: scripts/release/setup-secrets-wizard.sh
# Puts the Developer ID certificate, the notarisation Apple ID + app-specific password and the Sparkle EdDSA private key into GitHub Secrets for
# anzchy/picsee. Secrets are never printed and never written into the repository or a .env file.
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


run_wizard() {

TOTAL_STAGES=6
REPO="anzchy/picsee"
TEAM="GRT84NAK4T"
WORK=$(mktemp -d "${TMPDIR:-/tmp}/picsee-secrets.XXXXXX")
chmod 700 "$WORK"
cleanup() { [[ -d "$WORK" ]] && { find "$WORK" -type f -exec rm -P {} + 2>/dev/null || true; rm -rf "$WORK"; }; return 0; }
trap cleanup EXIT
export GH_REPO="$REPO"
has_secret() { gh secret list --json name -q '.[].name' 2>/dev/null | grep -qx "$1"; }

banner "picsee release signing secrets → GitHub ($REPO)"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Check GitHub access"
say "Secrets go to GitHub Actions for $REPO. Nothing is written to the repository or a .env file."
if ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
  warn "gh is not installed or not logged in. Run: gh auth login   then re-run this wizard."
  exit 1
fi
if ! gh secret list >/dev/null 2>&1; then
  warn "This gh login cannot read Actions secrets for $REPO (needs admin on the repo)."
  exit 1
fi
note "gh is logged in and can manage secrets for $REPO."
pause

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Developer ID Application certificate (you, in Xcode)"
say "Only the Account Holder of team $TEAM can create this certificate."
step "Open Xcode → Settings… (⌘,) → Accounts."
step "Select your Apple ID, team $TEAM → Manage Certificates…"
step "Click + (bottom left) → Developer ID Application. Xcode creates it and puts the private key in your login keychain."
step "Close the sheet."
pause "Press Enter when the certificate shows in the list"
until security find-identity -v -p codesigning | grep -q "Developer ID Application:.*($TEAM)"; do
  warn "No 'Developer ID Application … ($TEAM)' identity in the keychain yet."
  pause "Create it as above, then press Enter to check again"
done
note "Found a Developer ID Application identity for team $TEAM."
pause

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Export the certificate as .p12 (you, in Keychain Access)"
P12="$WORK/developer-id.p12"
if has_secret DEVELOPER_ID_P12_BASE64 && has_secret DEVELOPER_ID_P12_PASSWORD && confirm "The certificate is already in GitHub Secrets. Keep it and skip this stage?"; then
  note "Kept the existing DEVELOPER_ID_P12_* secrets."
else
say "Export the certificate together with its private key into a temporary folder this wizard deletes at the end."
open -a "Keychain Access" >/dev/null 2>&1 || true
step "Keychain Access → login keychain → My Certificates."
step "Find 'Developer ID Application: … ($TEAM)', expand it to see its private key, select the certificate."
step "File → Export Items… → format 'Personal Information Exchange (.p12)'."
step "Save it exactly as:  $P12"
note "Tip: in the save dialog press ⌘⇧G and paste the folder path: $WORK"
step "Choose an export password (you will type it here next)."
pause "Press Enter after saving the .p12"
until [[ -s "$P12" ]]; do
  warn "No file at $P12 yet."
  pause "Save it there, then press Enter"
done
ask_secret P12_PASSWORD "Type the .p12 export password:"
p12_opens() { openssl pkcs12 -in "$P12" -passin "pass:$P12_PASSWORD" -noout -legacy >/dev/null 2>&1 \
  || openssl pkcs12 -in "$P12" -passin "pass:$P12_PASSWORD" -noout >/dev/null 2>&1; }
until p12_opens; do
  warn "That password doesn't open the .p12."
  ask_secret P12_PASSWORD "Type the .p12 export password again:"
done
set_secret DEVELOPER_ID_P12_BASE64 "$(base64 -i "$P12")"
set_secret DEVELOPER_ID_P12_PASSWORD "$P12_PASSWORD"
set_secret KEYCHAIN_PASSWORD "$(openssl rand -base64 24)"
unset P12_PASSWORD
fi
pause

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Apple ID app-specific password for notarisation (you, in the browser)"
say "Notarisation signs in with your Apple ID and an app-specific password (user's choice, 2026-10-28: 「B，改成 app 专用密码」)."
say "This replaces the App Store Connect API key, so no App Store Connect access is needed."
if has_secret APPLE_ID && has_secret APPLE_APP_SPECIFIC_PASSWORD && confirm "Notarisation credentials are already in GitHub Secrets. Keep them and skip this stage?"; then
  note "Kept the existing APPLE_ID and APPLE_APP_SPECIFIC_PASSWORD secrets."
else
  open_url "https://account.apple.com/account/manage"
  step "Sign in with the Apple ID of team $TEAM (two-factor authentication)."
  step "Sign-In and Security → App-Specific Passwords → + (Generate)."
  step "Name it: picsee notarisation. Copy the password (format xxxx-xxxx-xxxx-xxxx). Apple shows it only once."
  ask APPLE_ID "Apple ID email of team $TEAM:"
  ask_secret APP_PW "Paste the app-specific password:"
  say "Checking the credentials with notarytool (lists past submissions; nothing is uploaded)…"
  until xcrun notarytool history --apple-id "$APPLE_ID" --password "$APP_PW" --team-id "$TEAM" >/dev/null 2>&1; do
    warn "notarytool could not sign in with that Apple ID, password and team $TEAM."
    note "Check the Apple ID, that the password is an app-specific one, and that the team's agreements are accepted."
    ask APPLE_ID "Apple ID email:"
    ask_secret APP_PW "App-specific password:"
  done
  note "notarytool accepted the credentials."
  set_secret APPLE_ID "$APPLE_ID"
  set_secret APPLE_APP_SPECIFIC_PASSWORD "$APP_PW"
  unset APP_PW
fi
pause

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Sparkle update-signing key (automatic)"
say "Downloads the latest Sparkle release tools and creates an EdDSA key pair for update signing."
if has_secret SPARKLE_ED_PRIVATE_KEY && [[ -s "$HOME/.picsee/release/sparkle-public-ed-key.txt" ]] && confirm "A Sparkle key is already in GitHub Secrets. Keep it and skip this stage?"; then
  note "Kept the existing Sparkle key; public key: $(cat "$HOME/.picsee/release/sparkle-public-ed-key.txt")"
else
SPARKLE_TAG=$(gh release view --repo sparkle-project/Sparkle --json tagName -q .tagName)
note "Sparkle $SPARKLE_TAG"
gh release download "$SPARKLE_TAG" --repo sparkle-project/Sparkle --pattern "Sparkle-${SPARKLE_TAG}.tar.xz" --dir "$WORK" >/dev/null
mkdir -p "$WORK/sparkle" && tar -xJf "$WORK/Sparkle-${SPARKLE_TAG}.tar.xz" -C "$WORK/sparkle"
GEN="$WORK/sparkle/bin/generate_keys"
say "Sparkle keeps the private key in your login keychain (account 'picsee'); macOS may ask to allow access."
"$GEN" --account picsee >/dev/null
"$GEN" --account picsee -x "$WORK/sparkle-private-key.txt" >/dev/null
PUB=$("$GEN" --account picsee -p | tail -1)
set_secret SPARKLE_ED_PRIVATE_KEY "$(cat "$WORK/sparkle-private-key.txt")"
mkdir -p "$HOME/.picsee/release"
printf '%s\n' "$PUB" > "$HOME/.picsee/release/sparkle-public-ed-key.txt"
note "Public key (not secret) saved to ~/.picsee/release/sparkle-public-ed-key.txt for #220 (Info.plist SUPublicEDKey):"
say "$PUB"
fi
pause

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Team variable and clean-up"
set_var DEVELOPMENT_TEAM "$TEAM"
cleanup
note "Temporary files (.p12, Sparkle private key export, Sparkle tools) securely deleted."
note "Secret names now in GitHub: $(gh secret list --json name -q '[.[].name]|join(", ")')"
pause "Press Enter to finish"

finish
}

run_wizard "$@"; exit
